# The output checks in plain words, in display order. Each forecast is
# checked before it is scored; a case passes a check when the check ran and
# none of the diagnostics it covers failed.
CHECKS = {
    "runs": "Runs without errors",
    "dates": "Forecasts the requested dates",
    "series": "Returns every series, in order",
    "shape": "Right number of steps and series",
    "finite": "No missing or infinite values",
    "quantiles": "Quantiles in order",
    "dependence": "Joint spread matches the answer key",
}
_CHECK_CODES = {
    "series": {"target_names", "target_mismatch"},
    "shape": {"point_shape", "quantile_shape", "sample_shape", "missing_prediction"},
    "quantiles": {
        "invalid_levels",
        "duplicate_levels",
        "nonmonotonic_levels",
        "missing_quantiles",
        "quantile_crossing",
    },
}


def _check_key(name):
    """Map a diagnostic name to the plain check it belongs to, if any."""
    if name in ("model_execution", "forecast_contract"):
        return "runs" if name == "model_execution" else None
    if name == "reference_covariance":
        return "dependence"
    if not name.startswith("contract_"):
        return None
    code = name[len("contract_") :]
    if code.startswith("index_"):
        return "dates"
    if code.startswith(("nonfinite_", "nonreal_")):
        return "finite"
    return next((key for key, codes in _CHECK_CODES.items() if code in codes), None)


def _case_checks(case):
    """Return ``{check: True/False}`` for the checks that ran on one case."""
    by_name = {}
    for diagnostic in case.diagnostics:
        by_name.setdefault(diagnostic.name, []).append(diagnostic)
    crashed = any(
        d.failed
        for name in ("model_execution", "forecast_contract")
        for d in by_name.get(name, [])
    )
    outcome = {"runs": not crashed}
    if crashed:
        return outcome
    failed = {_check_key(d.name) for d in case.diagnostics if d.failed}
    for key in ("dates", "series", "shape", "finite"):
        outcome[key] = key not in failed
    quantiles_given = any(
        d.status != "UNSUPPORTED" for d in by_name.get("quantile_accuracy", [])
    )
    if quantiles_given or "quantiles" in failed:
        outcome["quantiles"] = "quantiles" not in failed
    if any(
        d.status in ("PASS", "FAIL") for d in by_name.get("reference_covariance", [])
    ):
        outcome["dependence"] = "dependence" not in failed
    outcome.update((name, passed) for name, (passed, _) in _own_checks(case).items())
    return outcome


def _own_checks(case):
    """Return ``{name: (passed, title)}`` for the checks asked for with ``checks=`` that ran on one case.

    Their findings are named ``check_<name>`` and keep the check's title in
    their evidence, so a saved report reads without the check's function.
    """
    found = {}
    for diagnostic in case.diagnostics:
        name = (
            diagnostic.name[len("check_") :]
            if diagnostic.name.startswith("check_")
            else ""
        )
        if (
            not name
            or name in CHECKS
            or diagnostic.status not in ("PASS", "FAIL", "ERROR")
        ):
            continue
        title = (
            diagnostic.evidence.get("title")
            if isinstance(diagnostic.evidence, dict)
            else None
        )
        passed = found[name][0] if name in found else True
        found[name] = (
            passed and not diagnostic.failed,
            title if isinstance(title, str) and title else name,
        )
    return found


def _metrics_table(cases):
    """``TestReport.metrics`` for a list of CaseResults: their labels, then their metrics, NaN where not scored."""
    names = sorted(
        {name for case in cases for name in case.metrics}
    )  # as a saved report keeps them
    index = pd.RangeIndex(len(cases), name="case")
    seeds = [case.seed for case in cases]
    origins = [case.manifest.get("origin") for case in cases]
    labels = {"kind": [case.scenario for case in cases]}
    if any(seed is not None for seed in seeds):
        labels["seed"] = (
            seeds if None not in seeds else pd.Series(seeds, index=index, dtype=object)
        )
    if any(origin is not None for origin in origins):
        labels["origin"] = origins
    columns = {label: values for label, values in labels.items() if label not in names}
    scored = [all(_case_checks(case).values()) for case in cases]
    for name in names:
        columns[name] = [
            case.metrics[name] if ok and name in case.metrics else np.nan
            for case, ok in zip(cases, scored)
        ]
    return pd.DataFrame(columns, index=index)


