@dataclass
class TestReport:
    """Diagnostics and metrics for every case of one run, with run metadata.

    A PASS is scoped to a check; unsupported checks do not establish success.
    """

    __test__ = False  # Prevent pytest from trying to collect the dataclass.

    cases: list[CaseResult]
    metadata: dict = field(default_factory=dict)

    def __post_init__(self):
        if not isinstance(self.cases, list) or not isinstance(self.metadata, dict):
            raise ValueError(
                "report.cases must be a list and report.metadata must be an object"
            )
        for case in self.cases:
            if not isinstance(case, CaseResult):
                raise ValueError("report.cases must contain CaseResult objects")
            case.__post_init__()
        self.metadata = _json_safe(self.metadata)

    @property
    def summary(self):
        """Count cases, diagnostics by status, and failed cases.

        A case fails when any of its diagnostics is ``FAIL`` or ``ERROR``.
        """
        counts = Counter(
            diagnostic.status for case in self.cases for diagnostic in case.diagnostics
        )
        return {
            "cases": len(self.cases),
            "diagnostics": sum(counts.values()),
            "status_counts": {
                status.value: counts[status.value] for status in DiagnosticStatus
            },
            "failed_cases": sum(
                any(d.failed for d in case.diagnostics) for case in self.cases
            ),
        }

    @property
    def metrics(self):
        """Every case's metrics as a table: one row per case, in order, its labels first.

        ``kind`` is the case's kind, such as ``"ar1"``, or for your own data
        the name its cases were cut under; ``seed`` is its seed and ``origin``
        where its history ends, each when the cases have one. These are the
        manifest keys that ``compare(by=...)`` groups by, so
        ``report.metrics.groupby("kind")["mae"].mean()`` gives the mean error
        of each kind. One column per metric follows, in alphabetical order.
        A case that crashed or failed an output check is not scored, so its
        metrics are NaN, as in ``compare`` and the scorecard;
        ``case.metrics`` still holds any it recorded. The row label is the
        case's position in ``report.cases``. The table is made from the cases
        each time it is read, so it follows any change to them.
        """
        return _metrics_table(self.cases)

    def to_dict(self):
        """Revalidate the report and return it with its schema version and summary."""
        self.__post_init__()
        return {
            "schema_version": REPORT_SCHEMA_VERSION,
            "cases": _json_safe(self.cases),
            "metadata": _json_safe(self.metadata),
            "summary": self.summary,
        }

    def to_json(self, path=None):
        """Return the report as indented JSON text; ``save(path)`` writes it to a file.

        ``to_json(path)``, the old way to write the file, still writes it,
        returns the text and warns.
        """
        serialized = json.dumps(
            self.to_dict(), indent=2, sort_keys=True, allow_nan=False
        )
        if path is not None:
            _warn_deprecated(
                "report.to_json(path) is deprecated and will be removed in a later release: "
                "use report.save(path)"
            )
            Path(path).write_text(serialized + "\n", encoding="utf-8")
        return serialized

    def save(self, path):
        """Write the report to a JSON file at ``path`` and return ``path``; ``TestReport.load(path)`` reads it back.

        The file holds every case's metrics, findings and manifest and the
        run's metadata, as ``to_json()`` gives them: enough to replay a case
        with ``replay_case``, and no series or forecasts.
        """
        Path(path).write_text(self.to_json() + "\n", encoding="utf-8")
        return path

    @classmethod
    def from_dict(cls, payload):
        """Load schema 2.0 data without importing or constructing saved models.

        Unknown fields/statuses, malformed records, nonfinite metrics, and a
        saved summary inconsistent with the diagnostics are rejected. Metadata
        and evidence remain JSON data. The returned report owns copied values.
        A metric saved under an old name, such as ``mean_reference_mse`` by
        TimeGym 1.13.1, loads under its name now, ``avoidable_mse``, so old and
        new reports compare and replay.
        """
        payload = _report_json_value(payload)
        _report_fields(
            payload, {"schema_version", "cases", "metadata", "summary"}, "report"
        )
        if payload["schema_version"] != REPORT_SCHEMA_VERSION:
            raise ValueError(
                f"Unsupported report schema_version; expected {REPORT_SCHEMA_VERSION!r}"
            )
        if not isinstance(payload["cases"], list) or not isinstance(
            payload["metadata"], dict
        ):
            raise ValueError(
                "report.cases must be a list and report.metadata must be an object"
            )
        cases = []
        for index, record in enumerate(payload["cases"]):
            path = f"report.cases[{index}]"
            _report_fields(
                record, {"scenario", "seed", "diagnostics", "metrics", "manifest"}, path
            )
            if not isinstance(record["diagnostics"], list):
                raise ValueError(f"{path}.diagnostics must be a list")
            diagnostics = []
            for diagnostic_index, item in enumerate(record["diagnostics"]):
                diagnostic_path = f"{path}.diagnostics[{diagnostic_index}]"
                _report_fields(
                    item,
                    {"name", "status", "category", "message", "evidence"},
                    diagnostic_path,
                )
                diagnostics.append(DiagnosticResult(**_renamed_diagnostic(item)))
            cases.append(
                CaseResult(
                    record["scenario"],
                    record["seed"],
                    diagnostics,
                    _renamed_metrics(record["metrics"]),
                    record["manifest"],
                )
            )
        report = cls(cases=cases, metadata=payload["metadata"])
        # JSON comparison also distinguishes true from 1 and 1.0 from 1.
        if json.dumps(payload["summary"], sort_keys=True) != json.dumps(
            report.summary, sort_keys=True
        ):
            raise ValueError(
                "Stored report.summary disagrees with the derived diagnostic counts"
            )
        return report

    @classmethod
    def from_json(cls, text):
        """Parse JSON text/bytes, rejecting duplicate keys and nonfinite numbers.

        This method never interprets a string as a path. Use ``load(path)``
        for a saved report. Loading data does not execute replay or model code.
        """
        if not isinstance(text, (str, bytes, bytearray)):
            raise TypeError(
                "from_json expects JSON text or bytes; use TestReport.load(path) for a file"
            )

        def unique_object(pairs):
            result = {}
            for key, value in pairs:
                if key in result:
                    raise ValueError(f"Duplicate JSON object key: {key!r}")
                result[key] = value
            return result

        def invalid_constant(value):
            raise ValueError(f"Nonfinite JSON constant is not permitted: {value}")

        try:
            payload = json.loads(
                text, object_pairs_hook=unique_object, parse_constant=invalid_constant
            )
        except (ValueError, UnicodeError) as exc:
            raise ValueError(f"Invalid report JSON: {exc}") from exc
        return cls.from_dict(payload)

    @classmethod
    def load(cls, path):
        """Read and validate the report file at ``path``, as ``save`` wrote it; paths are explicit, never guessed."""
        return cls.from_json(Path(path).read_bytes())

    @classmethod
    def read(cls, path):
        """Read a report file by the old name of ``load``, with a warning."""
        _warn_deprecated(
            "TestReport.read(path) is deprecated and will be removed in a later release: "
            "use TestReport.load(path)"
        )
        return cls.load(path)

    @property
    def checks(self):
        """Count, per plain-language output check, the cases that passed and failed.

        Returns one dictionary per check that ran on at least one case, in the
        order of ``CHECKS`` and then the checks asked for with ``checks=``:
        ``{"check", "title", "passed", "failed"}``. Metrics are not checks:
        they have no pass mark.
        """
        counts, titles = {key: [0, 0] for key in CHECKS}, dict(CHECKS)
        for case in self.cases:
            for name, (_, title) in _own_checks(case).items():
                titles.setdefault(name, title)
            for key, passed in _case_checks(case).items():
                counts.setdefault(key, [0, 0])[0 if passed else 1] += 1
        return [
            {"check": key, "title": titles[key], "passed": passed, "failed": failed}
            for key, (passed, failed) in counts.items()
            if passed + failed
        ]

    def assert_passed(self):
        """Raise when an output check failed or the model raised; otherwise return self.

        The error names each failed check in plain words, then lists every
        failing case. Metrics never fail this gate: TimeGym sets no accuracy
        pass mark, so INCONCLUSIVE and UNSUPPORTED results do not raise.
        """
        failures = [
            f"  {case.scenario}[seed={case.seed}] {diagnostic.name}: {diagnostic.message}"
            for case in self.cases
            for diagnostic in case.diagnostics
            if diagnostic.failed
        ]
        if failures:
            failed = [
                f"{row['title']}: failed in {row['failed']} of {row['passed'] + row['failed']} cases"
                for row in self.checks
                if row["failed"]
            ]
            raise AssertionError(
                "TimeGym detected failures:\n" + "\n".join(failed + failures)
            )
        return self

    def compare(
        self,
        baseline,
        *,
        metric,
        by=None,
        cluster=None,
        alpha=0.05,
        higher_is_better=False,
        seed=0,
    ):
        """Compare this report with ``baseline`` on the same cases, one metric at a time; returns a ReportComparison.

        ``report.compare(baseline, metric="mae")`` is
        ``compare_reports(report, baseline, metric="mae")``: the same paired
        test, the same table and the same arguments. ``baseline`` is a report,
        or a run, made on the same cases in the same order; ``by`` gives one
        row per value of a manifest key, ``cluster`` names a manifest key whose
        cases move together, and lower is better unless
        ``higher_is_better=True``. To set several candidates against one
        baseline at once, use ``compare_reports([a, b], baseline, ...)``.
        """
        from timegym.diagnostics import compare_reports

        return compare_reports(
            self,
            baseline,
            metric=metric,
            by=by,
            cluster=cluster,
            alpha=alpha,
            higher_is_better=higher_is_better,
            seed=seed,
        )

    def replay_case(self, case_index=0):
        """Re-evaluate one case when its built-in model configuration is replayable."""
        from timegym.pipeline import _replay_case

        return _replay_case(self, case_index)
